     3989: png_image_free(png_image *image)
     3990: {
     3991:    /* Safely call the real function, but only if doing so is safe at this point
     3992:     * (if not inside an error handling context).  Otherwise assume
     3993:     * png_safe_execute will call this API after the return.
     3994:     */
     3995:    if (image != NULL && image->opaque != NULL &&
     3996:       image->opaque->error_buf == NULL)
     3997:    {
     3998:       png_image_free_function(image);
     3999:       image->opaque = NULL;
     4000:    }
     4001: }
